// Package ids makes record identities: UUIDv7, generated by the component before the insert, never by a database
// default (protocol 14, "record identity").
package ids

import "github.com/google/uuid"

// New returns a new UUIDv7 (millisecond ordered, unique across replicas and shell members without coordination).
func New() uuid.UUID { return uuid.Must(uuid.NewV7()) }
